    $$function parseAll(strings) {
    return strings.map(parseInt);
}$$,
    $$function parseAll(strings) {
    return strings.map(str => parseInt(str, 10));
}$$,
    $$parseAll(strings) should take an array of numeric strings and return an array of integers.$$,
    $$parseAll(["10", "10", "10"]) returns [10, NaN, 2].$$,
    $$Array.prototype.map passes THREE arguments to the callback: the element, its index, and the array. parseInt takes TWO arguments: the string, and the radix (base). So map calls parseInt('10', 0), parseInt('10', 1), and parseInt('10', 2). Base 0 defaults to 10, base 1 is invalid (NaN), and base 2 parses '10' as 2.$$,
    $$[{"input":[["10","10","10"]],"expected_output":[10,10,10]},{"input":[["11","12","13"]],"expected_output":[11,12,13]},{"input":[["1"]],"expected_output":[1]}]$$::jsonb,
    'published'
  )
  returning id
